gAm(){return"\u062e\u0632\u0646\u0629 GPS \u2014 \u0627\u0644\u0625\u0641\u0635\u0627\u062d"},
gLe(){return"\u062e\u0632\u0646\u0629 \u0627\u0644\u0648\u0633\u0627\u0626\u0637 \u2014 \u0627\u0644\u0625\u0641\u0635\u0627\u062d"},
goy(){return"\u0646\u0642\u0627\u0637"},
gBj(){return"\u0645\u0633\u062c\u064e\u0651\u0644 \u0627\u0644\u062f\u062e\u0648\u0644"},
gAR(){return"\u0635\u0648\u0631\u0629 \u0623\u0645\u0627\u0646"},
gAU(){return"\u0635\u0648\u0631\u0629 \u0623\u0645\u0627\u0646"},
gAS(){return"\u0627\u0644\u062a\u0642\u0637 \u0635\u0648\u0631\u0629 \u0625\u0630\u0627 \u0623\u0642\u0644\u0642\u0643 \u0645\u0648\u0642\u0641 \u0645\u0627 (\u0648\u062c\u0647\u060c \u0645\u0631\u0643\u0628\u0629\u060c \u0645\u0643\u0627\u0646\u2026). \u062a\u064f\u062d\u0641\u0638 \u0641\u064a \u062e\u0632\u0646\u0629 \u0645\u062e\u062a\u0648\u0645\u0629 \u0648\u0645\u0634\u0641\u0651\u0631\u0629: \u0644\u0627 \u0648\u0627\u0644\u062f\u0627\u0643 \u0648\u0644\u0627 \u0623\u064a \u0634\u062e\u0635 \u0622\u062e\u0631 \u064a\u0645\u0643\u0646\u0647 \u0631\u0624\u064a\u062a\u0647\u0627. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0644\u0644\u0645\u062d\u0642\u0651\u0642\u064a\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647\u0627 \u0625\u0644\u0627 \u0628\u0642\u0631\u0627\u0631 \u0642\u0636\u0627\u0626\u064a."},
gOr(){return"\u0627\u0644\u062a\u0642\u0627\u0637 \u0635\u0648\u0631\u0629 \u0623\u0645\u0627\u0646"},
gN_(){return"\u062a\u0645 \u062d\u0641\u0638 \u0627\u0644\u0635\u0648\u0631\u0629 \u0641\u064a \u0627\u0644\u062e\u0632\u0646\u0629 \u0627\u0644\u0645\u062e\u062a\u0648\u0645\u0629"},
gMZ(){return"\u063a\u064a\u0631 \u0645\u062a\u0635\u0644: \u062a\u0645 \u0648\u0636\u0639 \u0627\u0644\u0635\u0648\u0631\u0629 \u0641\u064a \u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0627\u0646\u062a\u0638\u0627\u0631 \u0644\u0644\u0625\u0631\u0633\u0627\u0644"},
gMY(){return"\u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0645\u0637\u0644\u0648\u0628: \u062a\u0639\u0630\u0651\u0631 \u062d\u0641\u0638 \u0627\u0644\u0635\u0648\u0631\u0629. \u062d\u0627\u0648\u0644 \u0645\u062c\u062f\u062f\u064b\u0627 \u0639\u0646\u062f \u0627\u0644\u0627\u062a\u0635\u0627\u0644."},
