gOh(){return"\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0644\u0644\u0625\u0631\u0633\u0627\u0644"},
N1(a){return"\u062a\u0645 \u0625\u0631\u0633\u0627\u0644 "+a+" \u0635\u0648\u0631\u0629"},
gI9(){return"\u062a\u0646\u0632\u064a\u0644"},
gPh(){return"\u062a\u0643\u0628\u064a\u0631"},
