gpj(){return"\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0645\u064a\u0644\u0627\u062f"},
gwf(){return"\u062a\u0627\u0631\u064a\u062e \u0645\u064a\u0644\u0627\u062f\u0643 \u0636\u0631\u0648\u0631\u064a \u0644\u0639\u0645\u0644 \u0628\u0639\u0636 \u0648\u0638\u0627\u0626\u0641 \u0627\u0644\u062a\u0637\u0628\u064a\u0642."},
