gMw(){return"\u0631\u0645\u0632 \u0627\u0644\u0631\u0628\u0637 (\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0648\u0627\u062d\u062f\u060c 30 \u062f\u0642\u064a\u0642\u0629)"},
gMs(){return"\u0639\u0644\u0649 \u0647\u0627\u062a\u0641 \u0627\u0644\u0634\u062e\u0635 \u0627\u0644\u0645\u062d\u0645\u064a: \u0627\u0641\u062a\u062d Lyhanna \u2190 \xab\u0634\u062e\u0635 \u0645\u062d\u0645\u064a: \u0644\u062f\u064a\u0651 \u0631\u0645\u0632 \u0627\u0642\u062a\u0631\u0627\u0646\xbb \u2190 \u0623\u062f\u062e\u0644 \u0647\u0630\u0627 \u0627\u0644\u0631\u0645\u0632."},
