gGM(){return"\u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u0631\u062f"},
gGN(){return"\u062d\u0627\u0645\u064d"},
gGJ(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u062a\u0635\u0627\u0644."},
