gGC(){return"\u0623\u0646\u062a \u0645\u0646 \u0633\u064a\u0631\u0633\u0644 \u0627\u0644\u0631\u0627\u0628\u0637. \u0627\u0644\u0634\u062e\u0635 \u064a\u0643\u062a\u0628 \u0628\u064a\u0627\u0646\u0627\u062a\u0647 \u0628\u0646\u0641\u0633\u0647 \u2014 \u0648\u0644\u0627 \u062a\u062f\u062e\u0644 \u0623\u0646\u062a \u0634\u064a\u0626\u064b\u0627."},
gGR(){return"\u0627\u0644\u0635\u0644\u0629 (\u062e\u0627\u0644\u0629\u060c \u0635\u062f\u064a\u0642\u060c \u062c\u0627\u0631\u2026)"},
gGI(){return"\u0645\u0644\u0627\u062d\u0638\u0629 \u0644\u0643 (\xab\u062c\u062f\u062a\u064a\xbb)"},
gGq(){return"\u062d\u0627\u0645\u064d \u0623\u064a\u0636\u064b\u0627 (\u064a\u062a\u0644\u0642\u0649 \u0627\u0644\u062a\u0646\u0628\u064a\u0647\u0627\u062a)"},
gGp(){return"\u0648\u0635\u064a \u0642\u0627\u0646\u0648\u0646\u064a (\u0648\u062d\u0627\u0645\u064d \u062f\u0627\u0626\u0645\u064b\u0627)"},
gGO(){return"\u0628\u0644\u063a \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u0642\u0635\u0649 (5)"},
gGz(){return"\u0628\u0644\u063a \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u0642\u0635\u0649 (2)"},
gGx(){return"\u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u062f\u0639\u0648\u0629"},
gGH(){return"\u0627\u0644\u062f\u0639\u0648\u0629 \u062c\u0627\u0647\u0632\u0629"},
